var ledger = new List<Transaction>
{
    new(1, Direction.Expense, 10m, "a", "small", new DateTime(2026, 5, 1)),
    new(2, Direction.Expense, 90m, "b", "big", new DateTime(2026, 5, 2)),
    new(3, Direction.Expense, 40m, "c", "mid", new DateTime(2026, 5, 3)),
    new(4, Direction.Expense, 20m, "d", "tiny", new DateTime(2026, 5, 4)),
    new(5, Direction.Expense, 30m, "e", "small2", new DateTime(2026, 5, 5)),
};
var s = Solution.MonthStatement(ledger, 2026, 5);
Cj.Eq(string.Join(",", s.Top), "big,mid,small2", "top 3 by amount desc");
var empty = Solution.MonthStatement(ledger, 2026, 12);
Cj.Eq(empty.Income, 0m, "no income");
Cj.Eq(empty.Top.Count, 0, "no entries");
